-- pg_morlet 0.3.14 -> 0.3.15 (generated by tests/gen_upgrade.py; do not edit).
-- morlet_time_pieces (#562): falls back to start time and rate on collections without a time-anchor table.
\echo Use "ALTER EXTENSION pg_morlet UPDATE TO '0.3.15'" to load this file. \quit

CREATE OR REPLACE FUNCTION public.morlet_time_pieces(collection regclass,recording_id text,rho float8 DEFAULT NULL)
RETURNS TABLE(piece integer,segment integer,lo bigint,hi bigint,n_ref bigint,t_ref numeric,dn numeric,dt numeric,
  kind text,u_ref numeric,na bigint,nb bigint,ua numeric,ub numeric,rho_used float8,period_ns numeric)
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rec record; rel regclass; active bigint:=0; num numeric; den numeric; rho_rec float8; start_ns numeric;
BEGIN
  IF collection IS NULL OR recording_id IS NULL OR (rho IS NOT NULL AND NOT (rho>=0 AND rho<1)) THEN
    RAISE EXCEPTION 'collection and recording_id are required, and rho must be in [0, 1)';
  END IF;
  EXECUTE format('SELECT sample_rate_hz,metadata FROM %s WHERE recording_id=$1',collection) INTO rec USING recording_id;
  IF rec.sample_rate_hz IS NULL THEN RAISE EXCEPTION 'recording % does not exist or is not visible',recording_id; END IF;
  SELECT x.num,x.den INTO num,den FROM public.morlet_rate_ratio(rec.sample_rate_hz) x;
  period_ns:=den*1000000000/num;
  IF rec.metadata#>'{time_axis,rho}' IS NOT NULL THEN
    IF jsonb_typeof(rec.metadata#>'{time_axis,rho}')<>'number' OR NOT ((rec.metadata#>>'{time_axis,rho}')::float8>=0
        AND (rec.metadata#>>'{time_axis,rho}')::float8<1) THEN
      RAISE EXCEPTION 'recording %: metadata time_axis.rho must be a number in [0, 1)',recording_id;
    END IF;
    rho_rec:=(rec.metadata#>>'{time_axis,rho}')::float8;
  END IF;
  SELECT to_regclass(format('%I.%I',n.nspname,cl.relname||'_time_anchors')) INTO rel
    FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  IF rel IS NOT NULL THEN
    EXECUTE format('SELECT count(*) FROM %1$s x WHERE x.recording_id=$1 AND NOT x.retracted
      AND NOT EXISTS(SELECT 1 FROM %1$s y WHERE y.supersedes=x.anchor_id)',rel) INTO active USING recording_id;
  END IF;
  -- a scalar, not a record: without the anchor table a record is never assigned, and reading a field of it fails
  -- even behind OR (#562)
  IF active=0 THEN
    start_ns:=public.morlet_recording_start_ns(rec.metadata);
    IF start_ns IS NULL THEN RETURN; END IF;
    RETURN QUERY SELECT 0,0,0::bigint,NULL::bigint,0::bigint,start_ns,num,den*1000000000,'start+rate'::text,
      NULL::numeric,NULL::bigint,NULL::bigint,NULL::numeric,NULL::numeric,NULL::float8,den*1000000000/num;
    RETURN;
  END IF;
  RETURN QUERY EXECUTE format($q$
    WITH a AS (
      SELECT x.sample_offset AS n,x.utc_ns::numeric AS t,x.uncertainty_ns::numeric AS u,x.source,
        row_number() OVER w AS i,
        (count(*) FILTER (WHERE x.break_before) OVER w - CASE WHEN first_value(x.break_before) OVER w THEN 1 ELSE 0 END)::integer AS seg
      FROM %1$s x WHERE x.recording_id=$1 AND NOT x.retracted AND NOT EXISTS(SELECT 1 FROM %1$s y WHERE y.supersedes=x.anchor_id)
      WINDOW w AS (ORDER BY x.sample_offset ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)),
    b AS (
      SELECT a.*,lead(a.n) OVER o AS n_next,lead(a.t) OVER o AS t_next,lead(a.u) OVER o AS u_next,
        lead(a.seg) OVER o AS seg_next,lead(a.source) OVER o AS src_next,
        lag(a.n) OVER o AS n_prev,lag(a.t) OVER o AS t_prev,lag(a.u) OVER o AS u_prev,lag(a.seg) OVER o AS seg_prev,
        lag(a.source) OVER o AS src_prev
      FROM a WINDOW o AS (ORDER BY a.n)),
    p AS (
      -- one piece per anchor: up to the next anchor; its slope from the next anchor of the segment, else from the
      -- previous one, else the declared rate
      SELECT b.i::integer AS piece,b.seg AS segment,b.n AS lo,b.n_next AS hi,b.n AS n_ref,b.t AS t_ref,
        CASE WHEN b.seg_next=b.seg THEN (b.n_next-b.n)::numeric WHEN b.seg_prev=b.seg THEN (b.n-b.n_prev)::numeric ELSE $2 END AS dn,
        CASE WHEN b.seg_next=b.seg THEN b.t_next-b.t WHEN b.seg_prev=b.seg THEN b.t-b.t_prev ELSE $3 END AS dt,
        CASE WHEN b.seg_next=b.seg THEN 'between' ELSE 'after' END AS kind,b.u AS u_ref,
        CASE WHEN b.seg_next=b.seg THEN b.n WHEN b.seg_prev=b.seg THEN b.n_prev END AS na,
        CASE WHEN b.seg_next=b.seg THEN b.n_next WHEN b.seg_prev=b.seg THEN b.n END AS nb,
        CASE WHEN b.seg_next=b.seg THEN b.u WHEN b.seg_prev=b.seg THEN b.u_prev END AS ua,
        CASE WHEN b.seg_next=b.seg THEN b.u_next WHEN b.seg_prev=b.seg THEN b.u END AS ub,
        -- the caller's ρ, else the recording's, else the default of the anchors involved (none if one is an estimate)
        coalesce($4,$5,CASE WHEN public.morlet_default_clock_rho(b.source) IS NULL
            OR (b.seg_next=b.seg AND public.morlet_default_clock_rho(b.src_next) IS NULL)
            OR (b.seg_next IS DISTINCT FROM b.seg AND b.seg_prev=b.seg AND public.morlet_default_clock_rho(b.src_prev) IS NULL)
          THEN NULL ELSE public.morlet_default_clock_rho(b.source) END) AS rho_used
      FROM b)
    SELECT p.piece,p.segment,p.lo,p.hi,p.n_ref,p.t_ref,p.dn,p.dt,p.kind,p.u_ref,p.na,p.nb,p.ua,p.ub,p.rho_used,$6::numeric
    FROM p
    UNION ALL
    -- the samples before the first anchor, extrapolated backwards with the first piece's slope
    SELECT 0,p.segment,0::bigint,p.lo,p.n_ref,p.t_ref,p.dn,p.dt,'before',p.u_ref,p.na,p.nb,p.ua,p.ub,p.rho_used,$6::numeric
    FROM p WHERE p.piece=1 AND p.lo>0
    ORDER BY 3$q$,rel) USING recording_id,num,den*1000000000,rho,rho_rec,period_ns;
END $$;
